import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  check,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
  boolean,
} from 'drizzle-orm/pg-core';
import { appSchema } from './app.schema.js';

// Registry of organization schemas (one per Platinum organization). The name
// is generated by the server; see src/db/org/schema.ts for the format.
export const orgSchemas = appSchema.table(
  'org_schemas',
  {
    name: text('name').primaryKey(),
    // The Platinum at the root of the organization. Null only while the
    // schema is being created, before its first account exists.
    rootAccountId: uuid('root_account_id').references(
      (): AnyPgColumn => accounts.id,
    ),
    // Set when the organization came from a promotion to Platinum (decision
    // 87): the schema it was detached from, who promoted whom and when, and
    // the person's sponsor in the source organization. All null for an
    // organization founded by a Platinum link.
    sourceSchema: text('source_schema').references(
      (): AnyPgColumn => orgSchemas.name,
    ),
    promotedBy: uuid('promoted_by').references((): AnyPgColumn => accounts.id),
    promotedAt: timestamp('promoted_at', { withTimezone: true }),
    previousRecommenderId: uuid('previous_recommender_id').references(
      (): AnyPgColumn => accounts.id,
    ),
    createdAt: timestamp('created_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (t) => [
    check('org_schemas_name_format', sql`${t.name} ~ '^org_[0-9a-f]{8}$'`),
    check(
      'org_schemas_promotion_shape',
      sql`(${t.sourceSchema} is null) = (${t.promotedBy} is null) and (${t.sourceSchema} is null) = (${t.promotedAt} is null)`,
    ),
  ],
);

// Global directory of accounts. It guarantees global uniqueness of e-mail and
// Partner number and says which organization schema holds the Partner row.
export const accounts = appSchema.table(
  'accounts',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    email: text('email').notNull(),
    // Null until the owner sets a password.
    passwordHash: text('password_hash'),
    // Null only for SuperAdministrator accounts.
    orgSchema: text('org_schema').references(
      (): AnyPgColumn => orgSchemas.name,
    ),
    isSuperAdmin: boolean('is_super_admin').notNull().default(false),
    locale: text('locale').notNull().default('pl'),
    // Partner number (ABO# / Numer PA / Geschäftspartnernummer) and the
    // country that issued it; unique together across all organizations.
    partnerNumber: text('partner_number'),
    partnerCountry: text('partner_country'),
    createdAt: timestamp('created_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    unique('accounts_email_key').on(t.email),
    unique('accounts_partner_number_key').on(t.partnerCountry, t.partnerNumber),
    check('accounts_email_lowercase', sql`${t.email} = lower(${t.email})`),
    check(
      'accounts_partner_number_pair',
      sql`(${t.partnerNumber} is null) = (${t.partnerCountry} is null)`,
    ),
    check(
      'accounts_org_schema_or_super_admin',
      sql`${t.isSuperAdmin} = (${t.orgSchema} is null)`,
    ),
  ],
);

// Which migration files of the organization track were applied to which
// organization schema (the track is run by our own runner, see
// src/db/org-migrator).
export const orgSchemaMigrations = appSchema.table(
  'org_schema_migrations',
  {
    schemaName: text('schema_name')
      .notNull()
      .references(() => orgSchemas.name, { onDelete: 'cascade' }),
    file: text('file').notNull(),
    hash: text('hash').notNull(),
    appliedAt: timestamp('applied_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.schemaName, t.file] })],
);

export type AccountRow = typeof accounts.$inferSelect;
export type NewAccountRow = typeof accounts.$inferInsert;
